import sys

INF = float('inf')


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    grid = data[2:2 + n]
    dist = [[0 if grid[r][c] == 'S' else INF for c in range(m)] for r in range(n)]
    changed = True
    while changed:
        changed = False
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '#':
                    continue
                best = dist[r][c]
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '#':
                        if dist[nr][nc] + 1 < best:
                            best = dist[nr][nc] + 1
                if best < dist[r][c]:
                    dist[r][c] = best
                    changed = True
    out = []
    for r in range(n):
        out.append(' '.join('-1' if grid[r][c] == '#' or dist[r][c] == INF else str(dist[r][c]) for c in range(m)))
    print('\n'.join(out))


main()

