import sys
from collections import deque


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    grid = data[2:2 + n]
    best = [[-1] * m for _ in range(n)]
    for sr in range(n):
        for sc in range(m):
            if grid[sr][sc] != 'S':
                continue
            seen = [[-1] * m for _ in range(n)]
            seen[sr][sc] = 0
            q = deque([(sr, sc)])
            while q:
                r, c = q.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '#' and seen[nr][nc] == -1:
                        seen[nr][nc] = seen[r][c] + 1
                        q.append((nr, nc))
            for r in range(n):
                for c in range(m):
                    d = seen[r][c]
                    if d != -1 and (best[r][c] == -1 or d < best[r][c]):
                        best[r][c] = d
    print('\n'.join(' '.join(map(str, row)) for row in best))


main()
